list_gift_cards.code:
final response = await client.giftCards.listGiftCards(
  queryParams: {'email': 'jane.doe@example.com', 'is_active': 'true'},
);
final result = response.map as Map;
for (final giftCard in result['gift_cards'] as List) {
  print('${(giftCard as Map)['code']} ${giftCard['balance']} ${giftCard['initial_amount']}');
}
final pagination = result['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');
